/**
 * Control commands. Every POST binds to a 32-hex request_id generated by the
 * adapter and persisted in sessionStorage before the request leaves, so a
 * retry after an uncertain outcome replays the same command instead of
 * creating a second one.
 */

export type CommandType = 'start_bot' | 'stop_bot';

export type CommandStatus = 'pending' | 'success' | 'failed' | 'uncertain';

export interface PendingCommand {
  path: string;
  command_type: CommandType;
  body: Record<string, string>; // contains request_id (32 lowercase hex)
  build: string;                // X-CatOS-Build sent with the request
  instance: string;             // X-CatOS-Instance sent with the request
  timestamp_ms: number;
}

export interface CommandRecord {
  request_id: string;
  command_type: CommandType;
  body: Record<string, string>;
  timestamp_ms: number;
  status: CommandStatus;
  http_status?: number;
  error_code?: string;
  run_id?: string;
}
